#!/usr/bin/env Rscript

# Truth-based FACS benchmark generated by Crispulator.jl 0.5.1.
#
# The primary comparison asks whether adding an unsorted 0--100% bulk sample
# to the low and high 25% tails improves recovery. Bulk overlaps both tails,
# so it is not an independent third FACS bin. Bulk and input are independent
# sequencing draws from the same cell frequencies, making their contrast a
# deliberate null reference.

options(stringsAsFactors = FALSE)
source(file.path("R", "method_palette.R"))

data_dir <- Sys.getenv(
  "CRISPULATOR_DATA_DIR",
  file.path("data", "derived", "crispulator_facs")
)
result_dir <- Sys.getenv(
  "CRISPULATOR_RESULT_DIR",
  file.path("results", "crispulator_facs")
)
figure_path <- Sys.getenv(
  "CRISPULATOR_FIGURE_PATH",
  file.path("figures", "crispulator_facs_benchmark.pdf")
)
dir.create(result_dir, recursive = TRUE, showWarnings = FALSE)
dir.create(dirname(figure_path), recursive = TRUE, showWarnings = FALSE)

required <- file.path(
  data_dir,
  c("counts.tsv", "sample_design.tsv", "guide_truth.tsv", "gene_truth.tsv")
)
if (!all(file.exists(required))) {
  stop(
    "Run `julia --project=julia julia/simulate_crispulator_facs.jl` first.",
    call. = FALSE
  )
}

count_table <- read.delim(required[1L], check.names = FALSE)
sample_data <- read.delim(required[2L], check.names = FALSE)
guide_truth <- read.delim(required[3L], check.names = FALSE)
gene_truth <- read.delim(required[4L], check.names = FALSE)
gene_truth$active <- tolower(as.character(gene_truth$active)) == "true"
counts <- as.matrix(count_table[, sample_data$sample, drop = FALSE])
storage.mode(counts) <- "double"
stopifnot(
  identical(count_table$guide, guide_truth$guide),
  identical(count_table$gene, guide_truth$gene),
  all(colSums(counts) > 0),
  all(table(sample_data$replicate) == length(unique(sample_data$sample_type)))
)
n_replicates <- length(unique(sample_data$replicate))
if (n_replicates < 1L) {
  stop("At least one screen replicate is required.")
}

# Load the RcppArmadillo weighted-crossproduct kernels when available.
cpp_library <- file.path("CB2", "src", paste0("CB2", .Platform$dynlib.ext))
if (file.exists(cpp_library) &&
    requireNamespace("Rcpp", quietly = TRUE) &&
    requireNamespace("RcppArmadillo", quietly = TRUE)) {
  suppressPackageStartupMessages(library(Rcpp))
  suppressPackageStartupMessages(library(RcppArmadillo))
  if (!"CB2" %in% names(getLoadedDLLs())) {
    dyn.load(cpp_library)
  }
  source(file.path("CB2", "R", "RcppExports.R"))
}
source(file.path("R", "bbreg.R"))

conditional_normal_mean <- function(lower, upper) {
  mass <- pnorm(upper) - pnorm(lower)
  (dnorm(lower) - dnorm(upper)) / mass
}
q25 <- qnorm(0.25)
sample_data$phenotype_z <- NA_real_
sample_data$phenotype_z[sample_data$sample_type == "low"] <-
  conditional_normal_mean(-Inf, q25)
sample_data$phenotype_z[sample_data$sample_type == "high"] <-
  conditional_normal_mean(-q25, Inf)
sample_data$phenotype_z[sample_data$sample_type == "bulk"] <- 0
sample_data$replicate <- factor(sample_data$replicate)

combine_guides <- function(guide_result) {
  groups <- split(seq_len(nrow(guide_result)), guide_result$gene)
  result <- do.call(rbind, lapply(names(groups), function(gene_name) {
    index <- groups[[gene_name]]
    valid <- is.finite(guide_result$estimate[index]) &
      is.finite(guide_result$p_value[index])
    index <- index[valid]
    if (!length(index)) {
      return(NULL)
    }
    signed_z <- sign(guide_result$estimate[index]) *
      qnorm(
        pmax(guide_result$p_value[index] / 2, .Machine$double.xmin),
        lower.tail = FALSE
      )
    combined_z <- sum(signed_z) / sqrt(length(signed_z))
    data.frame(
      gene = gene_name,
      n_guides = length(index),
      estimate = median(guide_result$estimate[index]),
      p_value = 2 * pnorm(-abs(combined_z)),
      converged_fraction = mean(guide_result$converged[index])
    )
  }))
  result$fdr <- p.adjust(result$p_value, method = "BH")
  rownames(result) <- NULL
  result
}

run_barcs <- function(label, sample_index, term = "phenotype_z") {
  design <- droplevels(sample_data[sample_index, , drop = FALSE])
  count_subset <- counts[, sample_index, drop = FALSE]
  formula <- if (term == "phenotype_z") {
    if (n_replicates >= 2L) {
      ~ phenotype_z + replicate
    } else {
      ~ phenotype_z
    }
  } else {
    ~ bulk_indicator + replicate
  }
  if (term == "bulk_indicator") {
    design$bulk_indicator <- as.integer(design$sample_type == "bulk")
  }
  start <- proc.time()
  guide_result <- bb_screen(
    counts = count_subset,
    totals = colSums(count_subset),
    data = design,
    formula = formula,
    term = term,
    guide = guide_truth$guide,
    gene = guide_truth$gene,
    min_total_count = 30,
    ncores = 4
  )
  elapsed <- unname((proc.time() - start)[["elapsed"]])
  calibrated <- bb_calibrate_controls(
    guide_result,
    guide_truth$class == "negcontrol",
    alpha = 0.05
  )
  gene_result <- combine_guides(calibrated)
  guide_consistency <- NULL
  if (n_replicates == 1L && term == "phenotype_z") {
    guide_consistency <- bb_gene_consistency(
      guide_result,
      control = guide_truth$class == "negcontrol",
      min_guides = 3L,
      alpha = 0.05,
      min_control_genes = 10L
    )
    write.csv(
      guide_consistency,
      file.path(
        result_dir,
        paste0(label, "_guide_consistency_gene_results.csv")
      ),
      row.names = FALSE
    )
    write.csv(
      data.frame(
        method = paste0(label, "_guide_consistency"),
        null_center = attr(guide_consistency, "null_center"),
        null_scale = attr(guide_consistency, "null_scale"),
        global_scale = attr(guide_consistency, "global_scale"),
        control_scale = attr(guide_consistency, "control_scale"),
        control_genes = attr(guide_consistency, "control_genes"),
        assumption = attr(guide_consistency, "null_assumption")
      ),
      file.path(
        result_dir,
        paste0(label, "_guide_consistency_calibration.csv")
      ),
      row.names = FALSE
    )
  }
  write.csv(
    calibrated,
    gzfile(file.path(result_dir, paste0(label, "_guide_results.csv.gz"))),
    row.names = FALSE
  )
  write.csv(
    gene_result,
    file.path(result_dir, paste0(label, "_gene_results.csv")),
    row.names = FALSE
  )
  write.csv(
    data.frame(
      method = label,
      elapsed_seconds = elapsed,
      guides_per_second = nrow(guide_result) / elapsed,
      converged_fraction = mean(guide_result$converged),
      control_scale = attr(calibrated, "control_scale")
    ),
    file.path(result_dir, paste0(label, "_runtime.csv")),
    row.names = FALSE
  )
  list(
    gene = gene_result,
    guide_consistency = guide_consistency
  )
}

make_guide_result <- function(estimate, standard_error, statistic, p_value) {
  converged <- is.finite(estimate) & is.finite(p_value)
  data.frame(
    gene = guide_truth$gene,
    guide = guide_truth$guide,
    estimate = estimate,
    std_error = standard_error,
    t_value = statistic,
    df = Inf,
    p_value = p_value,
    rho = NA_real_,
    mean_cpm = rowMeans(
      counts / rep(colSums(counts), each = nrow(counts)) * 1e6
    ),
    converged = converged,
    fdr = p.adjust(p_value, method = "BH")
  )
}

write_count_method <- function(label, guide_result, elapsed) {
  gene_result <- combine_guides(guide_result)
  write.csv(
    guide_result,
    gzfile(file.path(result_dir, paste0(label, "_guide_results.csv.gz"))),
    row.names = FALSE
  )
  write.csv(
    gene_result,
    file.path(result_dir, paste0(label, "_gene_results.csv")),
    row.names = FALSE
  )
  write.csv(
    data.frame(
      method = label,
      elapsed_seconds = elapsed,
      guides_per_second = nrow(guide_result) / elapsed
    ),
    file.path(result_dir, paste0(label, "_runtime.csv")),
    row.names = FALSE
  )
  gene_result
}

run_edger <- function(label, sample_index) {
  if (!requireNamespace("edgeR", quietly = TRUE)) {
    stop("The Bioconductor package `edgeR` is required.")
  }
  design_data <- droplevels(sample_data[sample_index, , drop = FALSE])
  formula <- if (n_replicates >= 2L) {
    ~ phenotype_z + replicate
  } else {
    ~ phenotype_z
  }
  design <- model.matrix(formula, data = design_data)
  count_subset <- counts[, sample_index, drop = FALSE]
  start <- proc.time()
  dge <- edgeR::DGEList(counts = count_subset)
  dge <- edgeR::calcNormFactors(dge)
  dge <- edgeR::estimateDisp(dge, design, robust = TRUE)
  fit <- edgeR::glmQLFit(dge, design, robust = TRUE)
  test <- edgeR::glmQLFTest(
    fit, coef = match("phenotype_z", colnames(design))
  )
  elapsed <- unname((proc.time() - start)[["elapsed"]])
  table <- test$table
  guide_result <- make_guide_result(
    estimate = table$logFC,
    standard_error = rep(NA_real_, nrow(table)),
    statistic = sqrt(pmax(table$F, 0)) * sign(table$logFC),
    p_value = table$PValue
  )
  write_count_method(label, guide_result, elapsed)
}

run_deseq2 <- function(label, sample_index) {
  if (!requireNamespace("DESeq2", quietly = TRUE)) {
    stop("The Bioconductor package `DESeq2` is required.")
  }
  design_data <- droplevels(sample_data[sample_index, , drop = FALSE])
  count_subset <- counts[, sample_index, drop = FALSE]
  start <- proc.time()
  dds <- DESeq2::DESeqDataSetFromMatrix(
    countData = round(count_subset),
    colData = design_data,
    design = if (n_replicates >= 2L) {
      ~ replicate + phenotype_z
    } else {
      ~ phenotype_z
    }
  )
  dds <- DESeq2::estimateSizeFactors(dds, type = "poscounts")
  dds <- suppressMessages(DESeq2::DESeq(
    dds,
    test = "Wald",
    quiet = TRUE,
    minReplicatesForReplace = Inf
  ))
  result <- DESeq2::results(
    dds,
    name = "phenotype_z",
    independentFiltering = FALSE,
    cooksCutoff = FALSE
  )
  elapsed <- unname((proc.time() - start)[["elapsed"]])
  guide_result <- make_guide_result(
    estimate = result$log2FoldChange,
    standard_error = result$lfcSE,
    statistic = result$stat,
    p_value = result$pvalue
  )
  write_count_method(label, guide_result, elapsed)
}

run_limma_voom <- function(label, sample_index) {
  if (!requireNamespace("limma", quietly = TRUE) ||
      !requireNamespace("edgeR", quietly = TRUE)) {
    stop("The Bioconductor packages `limma` and `edgeR` are required.")
  }
  design_data <- droplevels(sample_data[sample_index, , drop = FALSE])
  formula <- if (n_replicates >= 2L) {
    ~ phenotype_z + replicate
  } else {
    ~ phenotype_z
  }
  design <- model.matrix(formula, data = design_data)
  count_subset <- counts[, sample_index, drop = FALSE]
  start <- proc.time()
  dge <- edgeR::DGEList(counts = count_subset)
  dge <- edgeR::calcNormFactors(dge)
  transformed <- limma::voom(dge, design, plot = FALSE)
  fit <- limma::eBayes(
    limma::lmFit(transformed, design),
    robust = TRUE
  )
  coefficient <- match("phenotype_z", colnames(design))
  table <- limma::topTable(
    fit,
    coef = coefficient,
    number = Inf,
    sort.by = "none"
  )
  elapsed <- unname((proc.time() - start)[["elapsed"]])
  guide_result <- make_guide_result(
    estimate = table$logFC,
    standard_error = abs(table$logFC / table$t),
    statistic = table$t,
    p_value = table$P.Value
  )
  write_count_method(label, guide_result, elapsed)
}

three_sample_index <- sample_data$sample_type %in% c("low", "bulk", "high")
tail_index <- sample_data$sample_type %in% c("low", "high")
bulk_index <- sample_data$sample_type %in% c("input", "bulk")

