  `MAGeCK-MLE` = "MAGeCK",
  `edgeR-QL` = "edgeR",
  DESeq2 = "DESeq2",
  `limma-voom` = "limma-voom"
)
method_colours <- unname(
  barcs_method_colours[method_colour_keys[performance$method]]
)
par(mar = c(7.2, 4.2, 2.3, 0.8))
positions <- barplot(
  metric_matrix,
  beside = TRUE,
  col = rep(method_colours, each = nrow(metric_matrix)),
  density = rep(c(-1, 18, 35), times = ncol(metric_matrix)),
  angle = 45,
  border = method_colours,
  ylim = c(0, 1),
  ylab = "Truth-recovery metric",
  names.arg = method_labels,
  las = 2,
  cex.names = 0.67,
  main = "B  Sorted-bin recovery"
)
abline(h = 0.5, lty = 3, col = "#777777")
legend(
  "bottomright",
  legend = rownames(metric_matrix),
  fill = rep("#555555", 3L),
  border = "#333333",
  density = c(-1, 18, 35),
  angle = 45,
  cex = 0.68,
  bty = "n"
)

par(mar = c(4.2, 4.2, 2.3, 0.8))
if (n_replicates >= 2L) {
  bulk_effect <- merge(
    gene_truth,
    barcs_bulk[, c("gene", "estimate", "p_value")],
    by = "gene"
  )
  plot(
    bulk_effect$theoretical_phenotype,
    bulk_effect$estimate,
    pch = 16,
    cex = 0.55,
    col = ifelse(
      bulk_effect$active,
      paste0(barcs_method_colours[["BARCS"]], "99"),
      "#99999966"
    ),
    xlab = "True guide-aggregated phenotype",
    ylab = "Bulk-vs-input estimate",
    main = "C  Unsorted null reference",
    bty = "l"
  )
  abline(h = 0, lty = 2, col = "#555555")
  legend(
    "topright",
    legend = sprintf(
      "AUROC = %.2f\nSpearman = %.2f",
      metrics$auroc[metrics$method == "Bulk vs input"],
      cor(
        bulk_effect$theoretical_phenotype,
        bulk_effect$estimate,
        method = "spearman"
      )
    ),
    bty = "n",
    cex = 0.8
  )
} else {
  plot.new()
  title(main = "C  Pairwise contrasts")
  text(
    0.5, 0.55,
    "Not estimable with\none screen replicate",
    cex = 1
  )
  text(
    0.5, 0.34,
    "Two samples and two coefficients\nleave zero residual degrees of freedom",
    cex = 0.72
  )
}
dev.off()

print(metrics)
